        if (productMapper.count() == 0) {
            insertProduct("EMR_SR_COMPUTE", "StarRocks 计算资源包(特惠)", "COMPUTE",
                    new BigDecimal("99.00"), 3, 1, true,
                    "EMR StarRocks 计算加速包，限时特惠，限购1次");
            insertProduct("ECS_STANDARD", "ECS 标准计算包", "COMPUTE",
